//! Which files in a package generation owns, and may therefore replace or remove.
//!
//! A directory of generated files holds a record, `.dagger-generated.json`, of the
//! files generation wrote there and the SHA-256 of each. Generation replaces a file
//! only while it is still what generation wrote, and removes a file it no longer
//! generates only on the same condition, so an author's edit is never lost: it is
//! refused, or left in place.
//!
//! This is the ownership of Dagger's Go SDK, rule for rule and byte for byte in the
//! record (`ownedOverlay`, `ReadOwnership` and `checkOwnedParents` in
//! cmd/dagger-go-sdk-codegen/generator/ownership.go of github.com/dagger/go-sdk at
//! bb23e8d). Two things differ. A generated Rust file is recognised by a first line
//! that begins `// @generated`, where Go's begins `// Code generated by dagger.`. And
//! Go validates and then writes in one call, where [`plan_owned_overlay`] only
//! validates and returns what to write, so that a caller with several directories
//! writes nothing until every one of them has passed.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use serde::Deserialize;
use sha2::{Digest as _, Sha256};

use crate::diagnostic::{EngineDiagnostic, EngineDiagnosticCode};
use crate::{OperationRoot, RelativeOperationPath};

/// The record's file name in each directory of generated files.
pub(crate) const RECORD_FILE: &str = ".dagger-generated.json";

/// How every generated file begins.
pub(crate) const GENERATED_MARKER: &str = "// @generated";

/// What bringing one directory to its generated content writes and removes.
#[derive(Debug, Default, Eq, PartialEq)]
pub(crate) struct OwnedChanges {
    /// Files whose bytes change, the record among them, by operation path.
    pub(crate) writes: BTreeMap<RelativeOperationPath, Vec<u8>>,
    /// Files generation wrote before, no longer generates, and finds unchanged.
    pub(crate) removed: BTreeSet<RelativeOperationPath>,
}

/// Validates the generated content of one directory against what is there, and
/// returns the changes that bring the directory to it. Nothing is written.
///
/// `overlay` maps each generated file, by its path within `directory`, to its bytes;
/// it is empty for a directory whose content is no longer generated. `package` is the
/// directory messages name paths from.
///
/// # Errors
///
/// Returns a diagnostic when the record cannot be read, when a path crosses a
/// symlink, and when a file to replace holds an author's changes.
pub(crate) fn plan_owned_overlay(
    root: &OperationRoot,
    package: &RelativeOperationPath,
    directory: &RelativeOperationPath,
    overlay: &BTreeMap<String, Vec<u8>>,
) -> Result<OwnedChanges, EngineDiagnostic> {
    let location = Location {
        root: root.absolute(),
        package,
        directory,
    };
    location.check_parents(RECORD_FILE)?;
    let record_path = location.operation_path(RECORD_FILE)?;
    let existing_record = location.read(RECORD_FILE)?;
    let old = match &existing_record {
        Some(bytes) => read_record(bytes, &record_path)?,
        None => BTreeMap::new(),
    };

    let mut changes = OwnedChanges::default();
    let mut next = BTreeMap::new();
    for (path, data) in overlay {
        if !valid_path(path) || path == RECORD_FILE {
            return Err(EngineDiagnostic::new(
                EngineDiagnosticCode::GenerationFailed,
                Some(directory.as_str()),
                format!("invalid generated path {path:?}"),
            ));
        }
        location.check_parents(path)?;
        let existing = location.read(path)?;
        if let Some(existing) = &existing
            && existing != data
        {
            let recorded = old.get(path);
            if !generated(existing) || recorded.is_some_and(|hash| *hash != digest(existing)) {
                return Err(EngineDiagnostic::new(
                    EngineDiagnosticCode::OwnershipConflict,
                    Some(location.operation_path(path)?.as_str()),
                    format!(
                        "{} contains user changes; refusing to overwrite it",
                        location.display(path)
                    ),
                ));
            }
        }
        if existing.as_ref() != Some(data) {
            changes
                .writes
                .insert(location.operation_path(path)?, data.clone());
        }
        next.insert(path.clone(), digest(data));
    }
    for (path, hash) in &old {
        if next.contains_key(path) {
            continue;
        }
        location.check_parents(path)?;
        let Some(data) = location.read(path)? else {
            continue;
        };
        if generated(&data) && digest(&data) == *hash {
            changes.removed.insert(location.operation_path(path)?);
        }
    }
    let record = write_record(&next);
    if existing_record.as_ref() != Some(&record) {
        changes.writes.insert(record_path, record);
    }
    Ok(changes)
}

/// Returns whether a directory holds a record, without following a symlink to one.
pub(crate) fn has_record(root: &OperationRoot, directory: &RelativeOperationPath) -> bool {
    fs::symlink_metadata(directory.join_lexically(root.absolute()).join(RECORD_FILE)).is_ok()
}

struct Location<'a> {
    root: &'a Path,
    package: &'a RelativeOperationPath,
    directory: &'a RelativeOperationPath,
}

impl Location<'_> {
    fn operation_path(&self, path: &str) -> Result<RelativeOperationPath, EngineDiagnostic> {
        RelativeOperationPath::parse(&format!("{}/{path}", self.directory)).map_err(|_| {
            EngineDiagnostic::new(
                EngineDiagnosticCode::OutputPathEscape,
                Some(self.directory.as_str()),
                "generated path is not confined to its directory",
            )
        })
    }

    fn absolute(&self, path: &str) -> PathBuf {
        let mut absolute = self.directory.join_lexically(self.root);
        absolute.extend(path.split('/'));
        absolute
    }

    /// The path as the package's author reads it: from the package's directory.
    fn display(&self, path: &str) -> String {
        let directory = self.display_directory();
        if directory.is_empty() {
            path.to_owned()
        } else {
            format!("{directory}/{path}")
        }
    }

    fn display_directory(&self) -> &str {
        let directory = self.directory.as_str();
        if directory == self.package.as_str() {
            return "";
        }
        directory
            .strip_prefix(self.package.as_str())
            .and_then(|rest| rest.strip_prefix('/'))
            .unwrap_or(directory)
    }

    // No component of the directory or of a path within it may be a symlink: a write
    // through one would land outside the directory the record speaks for. A component
    // that does not exist yet is created by the write. Go also checks the directories
    // above its root; here they are the operation root, which is opened resolved.
    fn check_parents(&self, path: &str) -> Result<(), EngineDiagnostic> {
        let mut current = self.root.to_path_buf();
        for component in self.directory.as_str().split('/') {
            current.push(component);
            match fs::symlink_metadata(&current) {
                Ok(metadata) if metadata.file_type().is_symlink() => {
                    let directory = self.display_directory();
                    return Err(self.symlink(format!(
                        "generated root {} crosses a symlink",
                        if directory.is_empty() { "." } else { directory }
                    )));
                }
                Ok(metadata) if !metadata.is_dir() => {
                    return Err(self.not_directory(&current));
                }
                Ok(_) => {}
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
                Err(_) => return Err(self.unreadable(path)),
            }
        }
        let components = path.split('/').collect::<Vec<_>>();
        for (index, component) in components.iter().enumerate() {
            current.push(component);
            match fs::symlink_metadata(&current) {
                Ok(metadata) if metadata.file_type().is_symlink() => {
                    return Err(self.symlink(format!(
                        "generated path {} crosses a symlink",
                        self.display(path)
                    )));
                }
                Ok(metadata) if index + 1 < components.len() && !metadata.is_dir() => {
                    return Err(self.not_directory(&current));
                }
                Ok(_) => {}
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
                Err(_) => return Err(self.unreadable(path)),
            }
        }
        Ok(())
    }

    /// Reads a file that [`Self::check_parents`] has passed, or `None` when absent.
    fn read(&self, path: &str) -> Result<Option<Vec<u8>>, EngineDiagnostic> {
        let absolute = self.absolute(path);
        match fs::symlink_metadata(&absolute) {
            Ok(metadata) if metadata.is_file() => fs::read(&absolute)
                .map(Some)
                .map_err(|_| self.unreadable(path)),
            Ok(_) => Err(EngineDiagnostic::new(
                EngineDiagnosticCode::OwnershipConflict,
                Some(self.directory.as_str()),
                format!(
                    "{} is not a file; generation writes a file there",
                    self.display(path)
                ),
            )),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
            Err(_) => Err(self.unreadable(path)),
        }
    }

    fn symlink(&self, message: String) -> EngineDiagnostic {
        EngineDiagnostic::new(
            EngineDiagnosticCode::OutputSymlinkEscape,
            Some(self.directory.as_str()),
            message,
        )
    }

    fn not_directory(&self, absolute: &Path) -> EngineDiagnostic {
        let relative = absolute
            .strip_prefix(self.package.join_lexically(self.root))
            .unwrap_or(absolute)
            .to_string_lossy()
            .replace('\\', "/");
        EngineDiagnostic::new(
            EngineDiagnosticCode::OwnershipConflict,
            Some(self.directory.as_str()),
            format!("{relative} is not a directory; generation writes files beneath it"),
        )
    }

    fn unreadable(&self, path: &str) -> EngineDiagnostic {
        EngineDiagnostic::new(
            EngineDiagnosticCode::GenerationFailed,
            Some(self.directory.as_str()),
            format!("{} could not be read", self.display(path)),
        )
    }
}

fn generated(data: &[u8]) -> bool {
    data.starts_with(GENERATED_MARKER.as_bytes())
}

fn digest(data: &[u8]) -> String {
    format!("{:x}", Sha256::digest(data))
}

// Go's `fs.ValidPath`, less the root itself: slash-separated names, none of them
// empty, `.` or `..`. A record written on another system may not name a path with a
// backslash either.
fn valid_path(path: &str) -> bool {
    !path.is_empty()
        && !path.contains('\\')
        && path
            .split('/')
            .all(|name| !name.is_empty() && name != "." && name != "..")
}

#[derive(Deserialize)]
struct RecordDocument {
    #[serde(default)]
    version: Option<i64>,
    #[serde(default)]
    files: Option<BTreeMap<String, String>>,
}

fn read_record(
    bytes: &[u8],
    record: &RelativeOperationPath,
) -> Result<BTreeMap<String, String>, EngineDiagnostic> {
    let stale = |message: String| {
        EngineDiagnostic::new(
            EngineDiagnosticCode::OperationManifestStale,
            Some(record.as_str()),
            message,
        )
    };
    let document: RecordDocument = serde_json::from_slice(bytes)
        .map_err(|_| stale("read generated ownership: the record is not valid JSON".to_owned()))?;
    let version = document.version.unwrap_or(1);
    if version != 1 {
        return Err(stale(format!(
            "unsupported generated ownership version {version}"
        )));
    }
    let files = document.files.unwrap_or_default();
    for (path, hash) in &files {
        if !valid_path(path)
            || path == RECORD_FILE
            || hash.len() != 64
            || !hash.bytes().all(|byte| byte.is_ascii_hexdigit())
        {
            return Err(stale(format!("invalid generated ownership entry {path:?}")));
        }
    }
    Ok(files)
}

// The bytes Go's `json.MarshalIndent(Ownership, "", "  ")` writes, and a newline:
// `version` and then `files`, as the struct declares them, with the files in order.
fn write_record(files: &BTreeMap<String, String>) -> Vec<u8> {
    let mut record = String::from("{\n  \"version\": 1,\n  \"files\": {");
    for (index, (path, hash)) in files.iter().enumerate() {
        record.push_str(if index == 0 { "\n" } else { ",\n" });
        record.push_str("    ");
        record.push_str(&json_string(path));
        record.push_str(": ");
        record.push_str(&json_string(hash));
    }
    if !files.is_empty() {
        record.push_str("\n  ");
    }
    record.push_str("}\n}\n");
    record.into_bytes()
}

// Go escapes `<`, `>` and `&` in a JSON string, and the two Unicode line separators.
fn json_string(value: &str) -> String {
    serde_json::Value::String(value.to_owned())
        .to_string()
        .replace('<', "\\u003c")
        .replace('>', "\\u003e")
        .replace('&', "\\u0026")
        .replace('\u{2028}', "\\u2028")
        .replace('\u{2029}', "\\u2029")
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeMap;
    use std::fs;
    use std::path::Path;

    use super::{OwnedChanges, RECORD_FILE, digest, plan_owned_overlay, write_record};
    use crate::diagnostic::EngineDiagnosticCode;
    use crate::{EngineDiagnostic, OperationRoot, RelativeOperationPath};

    const PACKAGE: &str = "workspace/app";
    const DIRECTORY: &str = "workspace/app/src/dagger_clients/greeter";

    // Written by Go at the reference: `json.MarshalIndent` of
    // `generator.Ownership{Version: 1, Files: …}` with two spaces, and a newline, for
    // the files `mod.rs` = "one\n" and `greeter.rs` = "two\n".
    const GO_RECORD: &str = "{\n  \"version\": 1,\n  \"files\": {\n    \"greeter.rs\": \"27dd8ed44a83ff94d557f9fd0412ed5a8cbca69ea04922d88c01184a07300a5a\",\n    \"mod.rs\": \"2c8b08da5ce60398e1f19af0e5dccc744df274b826abe585eaba68c525434806\"\n  }\n}\n";
    const GO_EMPTY_RECORD: &str = "{\n  \"version\": 1,\n  \"files\": {}\n}\n";

    fn path(value: &str) -> RelativeOperationPath {
        RelativeOperationPath::parse(value).expect("fixture path must parse")
    }

    fn generated(body: &str) -> Vec<u8> {
        format!("// @generated\n{body}\n").into_bytes()
    }

    fn overlay(files: &[(&str, Vec<u8>)]) -> BTreeMap<String, Vec<u8>> {
        files
            .iter()
            .map(|(path, data)| ((*path).to_owned(), data.clone()))
            .collect()
    }

    fn plan(
        directory: &Path,
        files: &BTreeMap<String, Vec<u8>>,
    ) -> Result<OwnedChanges, EngineDiagnostic> {
        let root = OperationRoot::open(directory).expect("operation root must open");
        plan_owned_overlay(&root, &path(PACKAGE), &path(DIRECTORY), files)
    }

    fn apply(directory: &Path, changes: &OwnedChanges) {
        for (path, data) in &changes.writes {
            let destination = directory.join(path.as_str());
            fs::create_dir_all(destination.parent().expect("a file has a parent"))
                .expect("parent must be created");
            fs::write(destination, data).expect("file must be written");
        }
        for path in &changes.removed {
            fs::remove_file(directory.join(path.as_str())).expect("file must be removed");
        }
    }

    fn generate(directory: &Path, files: &BTreeMap<String, Vec<u8>>) -> OwnedChanges {
        let changes = plan(directory, files).expect("generation must be allowed");
        apply(directory, &changes);
        changes
    }

    fn names<'a>(paths: impl IntoIterator<Item = &'a RelativeOperationPath>) -> Vec<String> {
        paths
            .into_iter()
            .map(|path| {
                path.as_str()
                    .strip_prefix(&format!("{DIRECTORY}/"))
                    .expect("a change lies in the directory")
                    .to_owned()
            })
            .collect()
    }

    #[test]
    fn the_record_is_byte_for_byte_what_go_writes() {
        let files = BTreeMap::from([
            ("mod.rs".to_owned(), digest(b"one\n")),
            ("greeter.rs".to_owned(), digest(b"two\n")),
        ]);
        assert_eq!(String::from_utf8(write_record(&files)).unwrap(), GO_RECORD);
        assert_eq!(
            String::from_utf8(write_record(&BTreeMap::new())).unwrap(),
            GO_EMPTY_RECORD
        );
    }

    #[test]
    fn a_first_generation_writes_every_file_and_the_record() {
        let temporary = tempfile::tempdir().unwrap();
        let files = overlay(&[("mod.rs", generated("a")), ("greeter.rs", generated("b"))]);
        let changes = generate(temporary.path(), &files);
        assert_eq!(
            names(changes.writes.keys()),
            [RECORD_FILE, "greeter.rs", "mod.rs"]
        );
        assert!(changes.removed.is_empty());
        // The record lists the files and never itself.
        let record =
            fs::read_to_string(temporary.path().join(DIRECTORY).join(RECORD_FILE)).unwrap();
        assert!(record.contains("\"greeter.rs\"") && record.contains("\"mod.rs\""));
        assert!(!record.contains(RECORD_FILE));

        // The same content again changes nothing.
        assert_eq!(
            plan(temporary.path(), &files).unwrap(),
            OwnedChanges::default()
        );
    }

    #[test]
    fn an_unchanged_generated_file_is_replaced() {
        let temporary = tempfile::tempdir().unwrap();
        generate(temporary.path(), &overlay(&[("mod.rs", generated("a"))]));
        let changes = generate(temporary.path(), &overlay(&[("mod.rs", generated("b"))]));
        assert_eq!(names(changes.writes.keys()), [RECORD_FILE, "mod.rs"]);
        assert_eq!(
            fs::read(temporary.path().join(DIRECTORY).join("mod.rs")).unwrap(),
            generated("b")
        );
    }

    #[test]
    fn a_generated_file_no_record_lists_is_replaced() {
        let temporary = tempfile::tempdir().unwrap();
        let directory = temporary.path().join(DIRECTORY);
        fs::create_dir_all(&directory).unwrap();
        fs::write(directory.join("mod.rs"), generated("from elsewhere")).unwrap();
        let changes = generate(temporary.path(), &overlay(&[("mod.rs", generated("a"))]));
        assert_eq!(names(changes.writes.keys()), [RECORD_FILE, "mod.rs"]);
    }

    #[test]
    fn an_edited_generated_file_is_refused_in_gos_words() {
        let temporary = tempfile::tempdir().unwrap();
        generate(temporary.path(), &overlay(&[("mod.rs", generated("a"))]));
        let file = temporary.path().join(DIRECTORY).join("mod.rs");
        // The edit keeps the marker; the recorded hash gives it away.
        fs::write(&file, generated("a, edited")).unwrap();
        let error = plan(temporary.path(), &overlay(&[("mod.rs", generated("b"))])).unwrap_err();
        assert_eq!(error.code, EngineDiagnosticCode::OwnershipConflict);
        assert_eq!(
            error.message,
            "src/dagger_clients/greeter/mod.rs contains user changes; refusing to overwrite it"
        );
        assert_eq!(
            error.coordinate.as_deref(),
            Some("workspace/app/src/dagger_clients/greeter/mod.rs")
        );
        // An edit that happens to equal the new content is no conflict.
        fs::write(&file, generated("b")).unwrap();
        assert!(plan(temporary.path(), &overlay(&[("mod.rs", generated("b"))])).is_ok());
    }

    #[test]
    fn a_file_without_the_marker_is_refused_whatever_the_record_says() {
        let temporary = tempfile::tempdir().unwrap();
        let directory = temporary.path().join(DIRECTORY);
        fs::create_dir_all(&directory).unwrap();
        fs::write(directory.join("mod.rs"), "pub fn mine() {}\n").unwrap();
        let error = plan(temporary.path(), &overlay(&[("mod.rs", generated("a"))])).unwrap_err();
        assert!(
            error
                .message
                .ends_with("contains user changes; refusing to overwrite it")
        );

        // A recorded hash that matches does not make an unmarked file generated.
        fs::write(
            directory.join(RECORD_FILE),
            write_record(&BTreeMap::from([(
                "mod.rs".to_owned(),
                digest(b"pub fn mine() {}\n"),
            )])),
        )
        .unwrap();
        assert!(plan(temporary.path(), &overlay(&[("mod.rs", generated("a"))])).is_err());
    }

    #[test]
    fn only_unchanged_files_are_pruned() {
        let temporary = tempfile::tempdir().unwrap();
        let directory = temporary.path().join(DIRECTORY);
        generate(
            temporary.path(),
            &overlay(&[
                ("mod.rs", generated("index")),
                ("kept.rs", generated("kept")),
                ("edited.rs", generated("edited")),
                ("unmarked.rs", generated("unmarked")),
                ("deleted.rs", generated("deleted")),
                ("dropped.rs", generated("dropped")),
            ]),
        );
        fs::write(directory.join("edited.rs"), generated("edited by hand")).unwrap();
        fs::write(directory.join("unmarked.rs"), "pub fn mine() {}\n").unwrap();
        fs::remove_file(directory.join("deleted.rs")).unwrap();
        fs::write(directory.join("authored.rs"), generated("never recorded")).unwrap();

        let changes = generate(
            temporary.path(),
            &overlay(&[
                ("mod.rs", generated("index")),
                ("kept.rs", generated("kept")),
            ]),
        );
        assert_eq!(names(&changes.removed), ["dropped.rs"]);
        assert_eq!(names(changes.writes.keys()), [RECORD_FILE]);
        for survivor in [
            "edited.rs",
            "unmarked.rs",
            "authored.rs",
            "kept.rs",
            "mod.rs",
        ] {
            assert!(directory.join(survivor).exists(), "{survivor}");
        }
        assert!(!directory.join("dropped.rs").exists());
    }

    #[test]
    fn a_directory_no_longer_generated_keeps_an_emptied_record() {
        let temporary = tempfile::tempdir().unwrap();
        let directory = temporary.path().join(DIRECTORY);
        generate(
            temporary.path(),
            &overlay(&[("mod.rs", generated("a")), ("greeter.rs", generated("b"))]),
        );
        fs::write(directory.join("greeter.rs"), generated("b, edited")).unwrap();

        let changes = generate(temporary.path(), &BTreeMap::new());
        assert_eq!(names(&changes.removed), ["mod.rs"]);
        assert_eq!(names(changes.writes.keys()), [RECORD_FILE]);
        assert_eq!(
            fs::read_to_string(directory.join(RECORD_FILE)).unwrap(),
            GO_EMPTY_RECORD
        );
        assert!(directory.join("greeter.rs").exists());
        // And again: the emptied record is already there.
        assert_eq!(
            plan(temporary.path(), &BTreeMap::new()).unwrap(),
            OwnedChanges::default()
        );
    }

    #[cfg(unix)]
    #[test]
    fn a_path_or_a_root_that_crosses_a_symlink_is_refused() {
        use std::os::unix::fs::symlink;

        let temporary = tempfile::tempdir().unwrap();
        let directory = temporary.path().join(DIRECTORY);
        fs::create_dir_all(&directory).unwrap();
        let elsewhere = temporary.path().join("elsewhere");
        fs::create_dir_all(&elsewhere).unwrap();
        fs::write(elsewhere.join("mod.rs"), generated("a")).unwrap();

        // A generated path that is a symlink.
        symlink(elsewhere.join("mod.rs"), directory.join("mod.rs")).unwrap();
        let error = plan(temporary.path(), &overlay(&[("mod.rs", generated("b"))])).unwrap_err();
        assert_eq!(error.code, EngineDiagnosticCode::OutputSymlinkEscape);
        assert_eq!(
            error.message,
            "generated path src/dagger_clients/greeter/mod.rs crosses a symlink"
        );
        fs::remove_file(directory.join("mod.rs")).unwrap();

        // A record that is a symlink.
        fs::write(elsewhere.join(RECORD_FILE), GO_EMPTY_RECORD).unwrap();
        symlink(elsewhere.join(RECORD_FILE), directory.join(RECORD_FILE)).unwrap();
        let error = plan(temporary.path(), &BTreeMap::new()).unwrap_err();
        assert_eq!(
            error.message,
            "generated path src/dagger_clients/greeter/.dagger-generated.json crosses a symlink"
        );

        // A root that is a symlink.
        fs::remove_dir_all(&directory).unwrap();
        symlink(&elsewhere, &directory).unwrap();
        let error = plan(temporary.path(), &overlay(&[("mod.rs", generated("b"))])).unwrap_err();
        assert_eq!(error.code, EngineDiagnosticCode::OutputSymlinkEscape);
        assert_eq!(
            error.message,
            "generated root src/dagger_clients/greeter crosses a symlink"
        );
        assert_eq!(fs::read(elsewhere.join("mod.rs")).unwrap(), generated("a"));
    }

    #[test]
    fn a_record_that_cannot_be_trusted_is_refused() {
        for (record, message) in [
            (
                "not json",
                "read generated ownership: the record is not valid JSON",
            ),
            (
                "{\"version\": 2, \"files\": {}}",
                "unsupported generated ownership version 2",
            ),
            (
                "{\"version\": 1, \"files\": {\"../mod.rs\": \"00\"}}",
                "invalid generated ownership entry \"../mod.rs\"",
            ),
            (
                "{\"version\": 1, \"files\": {\"mod.rs\": \"abc\"}}",
                "invalid generated ownership entry \"mod.rs\"",
            ),
            (
                "{\"version\": 1, \"files\": {\".dagger-generated.json\": \"2c8b08da5ce60398e1f19af0e5dccc744df274b826abe585eaba68c525434806\"}}",
                "invalid generated ownership entry \".dagger-generated.json\"",
            ),
        ] {
            let temporary = tempfile::tempdir().unwrap();
            let directory = temporary.path().join(DIRECTORY);
            fs::create_dir_all(&directory).unwrap();
            fs::write(directory.join(RECORD_FILE), record).unwrap();
            let error = plan(temporary.path(), &BTreeMap::new()).unwrap_err();
            assert_eq!(error.code, EngineDiagnosticCode::OperationManifestStale);
            assert_eq!(error.message, message);
        }
        // Go reads a record without `version` or `files` as an empty one.
        let temporary = tempfile::tempdir().unwrap();
        let directory = temporary.path().join(DIRECTORY);
        fs::create_dir_all(&directory).unwrap();
        fs::write(directory.join(RECORD_FILE), "{}").unwrap();
        assert!(plan(temporary.path(), &BTreeMap::new()).is_ok());
    }
}
